import { createRequire } from 'node:module';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { CodexRuntimeService } = require('./codex_runtime_service');

function bucket(limitId, usedPercent, overrides = {}) {
    return {
        credits: null,
        individualLimit: null,
        limitId,
        limitName: limitId === 'codex' ? 'Codex' : null,
        planType: 'plus',
        primary: { resetsAt: 100, usedPercent, windowDurationMins: 300 },
        rateLimitReachedType: null,
        secondary: null,
        ...overrides,
    };
}

describe('CodexRuntimeService', () => {
    it('publishes each confirmed update mismatch once per session and replays latest state', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribeUpdateRequired(listener);

        expect(service.publishUpdateRequired('0.144.6', '0.146.0')).toBe(true);
        expect(service.publishUpdateRequired('0.144.6', '0.146.0')).toBe(false);
        expect(listener).toHaveBeenCalledOnce();
        expect(listener).toHaveBeenCalledWith({ cacheVersion: '0.146.0', runningVersion: '0.144.6' });

        const lateListener = vi.fn();
        service.subscribeUpdateRequired(lateListener);
        expect(lateListener).toHaveBeenCalledWith({ cacheVersion: '0.146.0', runningVersion: '0.144.6' });
    });

    it('normalizes multi-bucket snapshots and publishes current state to subscribers', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);

        expect(service.publishRateLimits({
            rateLimitResetCredits: { availableCount: 0, credits: [] },
            rateLimits: bucket('codex', 10),
            rateLimitsByLimitId: {
                codex: bucket(null, 20),
                review: bucket('review', 40, {
                    primary: null,
                    secondary: { resetsAt: null, usedPercent: 40, windowDurationMins: null },
                }),
            },
        }, 200)).toBe(true);

        expect(service.getSnapshot()).toEqual({
            available: true,
            buckets: [
                expect.objectContaining({ limitId: 'codex', primary: expect.objectContaining({ usedPercent: 20 }) }),
                expect.objectContaining({ limitId: 'review', secondary: expect.objectContaining({ usedPercent: 40 }) }),
            ],
            observedAt: 200,
            rateLimitResetCredits: { availableCount: 0, credits: [] },
        });
        const lateListener = vi.fn();
        service.subscribe(lateListener);
        expect(listener).toHaveBeenCalledOnce();
        expect(lateListener).toHaveBeenCalledWith(service.getSnapshot());
    });

    it('merges sparse updates without erasing other buckets or nullable account fields', () => {
        const service = new CodexRuntimeService();
        service.publishRateLimits({
            rateLimitResetCredits: { availableCount: 1, credits: null },
            rateLimits: bucket('codex', 10),
            rateLimitsByLimitId: {
                codex: bucket('codex', 10),
                review: bucket('review', 40),
            },
        }, 100);

        service.publishRateLimits({rateLimits: bucket('codex', 70, { credits: null, limitName: null, planType: null })}, 101, true);

        expect(service.getSnapshot()).toMatchObject({
            buckets: [
                { credits: null, limitId: 'codex', limitName: 'Codex', planType: 'plus', primary: { usedPercent: 70 } },
                { limitId: 'review', primary: { usedPercent: 40 } },
            ],
            rateLimitResetCredits: { availableCount: 1, credits: null },
        });
    });

    it('accepts valid sparse updates with omitted optional fields', () => {
        const service = new CodexRuntimeService();
        service.publishRateLimits({
            rateLimits: bucket('codex', 20),
            rateLimitsByLimitId: null,
        }, 10);

        expect(service.publishRateLimits({
            rateLimits: {
                limitId: 'codex',
                primary: { usedPercent: 45 },
            },
        }, 11, true)).toBe(true);
        expect(service.getSnapshot()).toMatchObject({
            buckets: [{
                limitId: 'codex',
                limitName: 'Codex',
                primary: { resetsAt: 100, usedPercent: 45, windowDurationMins: 300 },
            }],
            observedAt: 11,
        });
    });

    it('rejects malformed and older reports without erasing newer data', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);
        service.publishRateLimits({ rateLimits: bucket('codex', 80) }, 200);

        expect(service.publishRateLimits({ rateLimits: bucket('codex', 10) }, 199)).toBe(false);
        expect(service.publishRateLimits({ rateLimits: { ...bucket('codex', 10), primary: { usedPercent: 'bad' } } }, 201)).toBe(false);
        expect(service.getSnapshot()).toMatchObject({
            buckets: [{ limitId: 'codex', primary: { usedPercent: 80 } }],
            observedAt: 200,
        });
        expect(listener).toHaveBeenCalledOnce();
    });

    it('publishes unavailable state without fabricating usage and keeps no persistence dependency', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);

        expect(service.publishUnavailable(300)).toBe(true);
        expect(service.getSnapshot()).toEqual({
            available: false,
            buckets: [],
            observedAt: 300,
            rateLimitResetCredits: null,
        });
        expect(listener).toHaveBeenCalledWith(service.getSnapshot());
        expect(Object.hasOwn(service, 'persistConversation')).toBe(false);
    });
});

const DEFAULT_RATE_LIMIT_ID = 'default';
const RATE_LIMIT_EVENT = 'rateLimits';
const UPDATE_REQUIRED_EVENT = 'updateRequired';

function nullableString(value) {
    return value === undefined || value === null || typeof value === 'string';
}

function nullableNumber(value) {
    return value === undefined || value === null || (typeof value === 'number' && Number.isFinite(value));
}

function normalizeWindow(window) {
    if (window === undefined) return undefined;
    if (window === null) return null;
    if (!window || typeof window !== 'object' || Array.isArray(window)) return undefined;
    if (typeof window.usedPercent !== 'number' || !Number.isFinite(window.usedPercent)) return undefined;
    if (!nullableNumber(window.windowDurationMins) || !nullableNumber(window.resetsAt)) return undefined;

    return {
        resetsAt: window.resetsAt,
        usedPercent: window.usedPercent,
        windowDurationMins: window.windowDurationMins,
    };
}

function normalizeCredits(credits) {
    if (credits === undefined) return undefined;
    if (credits === null) return null;
    if (!credits || typeof credits !== 'object' || Array.isArray(credits)) return undefined;
    if (typeof credits.hasCredits !== 'boolean' || typeof credits.unlimited !== 'boolean') return undefined;
    if (!nullableString(credits.balance)) return undefined;

    return {
        balance: credits.balance,
        hasCredits: credits.hasCredits,
        unlimited: credits.unlimited,
    };
}

function normalizeIndividualLimit(individualLimit) {
    if (individualLimit === undefined) return undefined;
    if (individualLimit === null) return null;
    if (!individualLimit || typeof individualLimit !== 'object' || Array.isArray(individualLimit)) return undefined;
    if (typeof individualLimit.limit !== 'string' || typeof individualLimit.used !== 'string') return undefined;
    if (typeof individualLimit.remainingPercent !== 'number' || !Number.isFinite(individualLimit.remainingPercent)) return undefined;
    if (typeof individualLimit.resetsAt !== 'number' || !Number.isFinite(individualLimit.resetsAt)) return undefined;

    return {
        limit: individualLimit.limit,
        remainingPercent: individualLimit.remainingPercent,
        resetsAt: individualLimit.resetsAt,
        used: individualLimit.used,
    };
}

function normalizeBucket(value, fallbackLimitId) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
    if (!nullableString(value.limitId) || !nullableString(value.limitName)) return null;
    if (!nullableString(value.planType) || !nullableString(value.rateLimitReachedType)) return null;
    const primary = normalizeWindow(value.primary);
    const secondary = normalizeWindow(value.secondary);
    const credits = normalizeCredits(value.credits);
    const individualLimit = normalizeIndividualLimit(value.individualLimit);
    const hasInvalidField = (value.primary !== undefined && primary === undefined)
        || (value.secondary !== undefined && secondary === undefined)
        || (value.credits !== undefined && credits === undefined)
        || (value.individualLimit !== undefined && individualLimit === undefined);
    if (hasInvalidField) return null;
    const hasLimitData = fallbackLimitId !== null
        || Object.values(value).some((field) => field !== undefined && field !== null);
    if (!hasLimitData) return null;

    return {
        credits,
        individualLimit,
        limitId: value.limitId ?? fallbackLimitId ?? DEFAULT_RATE_LIMIT_ID,
        limitName: value.limitName,
        planType: value.planType,
        primary,
        rateLimitReachedType: value.rateLimitReachedType,
        secondary,
    };
}

function completeWindow(window) {
    if (!window) return null;

    return {
        resetsAt: window.resetsAt ?? null,
        usedPercent: window.usedPercent,
        windowDurationMins: window.windowDurationMins ?? null,
    };
}

function completeBucket(bucket) {
    return {
        credits: bucket.credits ?? null,
        individualLimit: bucket.individualLimit ?? null,
        limitId: bucket.limitId,
        limitName: bucket.limitName ?? null,
        planType: bucket.planType ?? null,
        primary: completeWindow(bucket.primary),
        rateLimitReachedType: bucket.rateLimitReachedType ?? null,
        secondary: completeWindow(bucket.secondary),
    };
}

function normalizeResetCredit(credit) {
    if (!credit || typeof credit !== 'object' || Array.isArray(credit)) return null;
    if (typeof credit.id !== 'string' || typeof credit.resetType !== 'string' || typeof credit.status !== 'string') return null;
    if (typeof credit.grantedAt !== 'number' || !Number.isFinite(credit.grantedAt)) return null;
    if (!nullableNumber(credit.expiresAt) || !nullableString(credit.title) || !nullableString(credit.description)) return null;

    return {
        description: credit.description,
        expiresAt: credit.expiresAt,
        grantedAt: credit.grantedAt,
        id: credit.id,
        resetType: credit.resetType,
        status: credit.status,
        title: credit.title,
    };
}

function normalizeResetCredits(summary) {
    if (summary === null || summary === undefined) return null;
    if (!summary || typeof summary !== 'object' || Array.isArray(summary)) return undefined;
    if (!Number.isSafeInteger(summary.availableCount) || summary.availableCount < 0) return undefined;
    if (summary.credits !== null && !Array.isArray(summary.credits)) return undefined;
    const credits = summary.credits?.map(normalizeResetCredit) ?? null;
    if (credits?.some((credit) => credit === null)) return undefined;

    return { availableCount: summary.availableCount, credits };
}

function normalizeBuckets(payload) {
    const bucketEntries = payload.rateLimitsByLimitId && typeof payload.rateLimitsByLimitId === 'object'
        && !Array.isArray(payload.rateLimitsByLimitId)
        ? Object.entries(payload.rateLimitsByLimitId)
        : [];
    if (bucketEntries.length > 0) {
        const buckets = bucketEntries.map(([limitId, bucket]) => normalizeBucket(bucket, limitId));

        return buckets.some((bucket) => bucket === null) ? null : buckets;
    }
    const bucket = normalizeBucket(payload.rateLimits, null);

    return bucket ? [bucket] : null;
}

function mergeWindow(current, incoming) {
    if (!incoming) return current;
    if (!current) return incoming;

    return {
        resetsAt: incoming.resetsAt ?? current.resetsAt,
        usedPercent: incoming.usedPercent,
        windowDurationMins: incoming.windowDurationMins ?? current.windowDurationMins,
    };
}

function mergeBucket(current, incoming) {
    if (!current) return incoming;

    return {
        credits: incoming.credits ?? current.credits,
        individualLimit: incoming.individualLimit ?? current.individualLimit,
        limitId: incoming.limitId,
        limitName: incoming.limitName ?? current.limitName,
        planType: incoming.planType ?? current.planType,
        primary: mergeWindow(current.primary, incoming.primary),
        rateLimitReachedType: incoming.rateLimitReachedType ?? current.rateLimitReachedType,
        secondary: mergeWindow(current.secondary, incoming.secondary),
    };
}

class CodexRuntimeService {
    constructor() {
        this.events = new EventTarget();
        this.publishedUpdateMismatches = new Set();
        this.snapshot = null;
        this.updateRequiredSnapshot = null;
    }

    getSnapshot() {
        return this.snapshot ? structuredClone(this.snapshot) : null;
    }

    subscribe(listener) {
        const handleRateLimits = (event) => listener(event.detail);
        this.events.addEventListener(RATE_LIMIT_EVENT, handleRateLimits);
        if (this.snapshot) listener(this.getSnapshot());

        return () => this.events.removeEventListener(RATE_LIMIT_EVENT, handleRateLimits);
    }

    subscribeUpdateRequired(listener) {
        const handleUpdateRequired = (event) => listener(event.detail);
        this.events.addEventListener(UPDATE_REQUIRED_EVENT, handleUpdateRequired);
        if (this.updateRequiredSnapshot) listener(structuredClone(this.updateRequiredSnapshot));

        return () => this.events.removeEventListener(UPDATE_REQUIRED_EVENT, handleUpdateRequired);
    }

    publishUpdateRequired(runningVersion, cacheVersion) {
        if (typeof runningVersion !== 'string' || runningVersion.length === 0) {
            throw new Error('Running Codex version is required');
        }
        if (typeof cacheVersion !== 'string' || cacheVersion.length === 0) {
            throw new Error('Codex cache client version is required');
        }
        const mismatchKey = `${runningVersion}\u0000${cacheVersion}`;
        if (this.publishedUpdateMismatches.has(mismatchKey)) return false;

        this.publishedUpdateMismatches.add(mismatchKey);
        this.updateRequiredSnapshot = { cacheVersion, runningVersion };
        this.events.dispatchEvent(new CustomEvent(UPDATE_REQUIRED_EVENT, {detail: structuredClone(this.updateRequiredSnapshot)}));

        return true;
    }

    publishRateLimits(payload, observedAt, sparse = false) {
        if (!Number.isFinite(observedAt)) throw new Error('Invalid Codex rate-limit observation time');
        if (this.snapshot && observedAt < this.snapshot.observedAt) return false;
        if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return false;
        const buckets = normalizeBuckets(payload);
        const resetCredits = normalizeResetCredits(payload.rateLimitResetCredits);
        if (!buckets || resetCredits === undefined) return false;
        const currentBuckets = new Map((this.snapshot?.buckets ?? []).map((bucket) => [bucket.limitId, bucket]));
        if (sparse) {
            for (const bucket of buckets) currentBuckets.set(bucket.limitId, mergeBucket(currentBuckets.get(bucket.limitId), bucket));
        }
        const normalizedBuckets = (sparse ? [...currentBuckets.values()] : buckets).map(completeBucket);
        const rateLimitResetCredits = sparse && resetCredits === null
            ? this.snapshot?.rateLimitResetCredits ?? null
            : resetCredits;
        this.snapshot = {
            available: true,
            buckets: normalizedBuckets,
            observedAt,
            rateLimitResetCredits,
        };
        this.notify();

        return true;
    }

    publishUnavailable(observedAt) {
        if (!Number.isFinite(observedAt)) throw new Error('Invalid Codex rate-limit observation time');
        if (this.snapshot && observedAt < this.snapshot.observedAt) return false;
        this.snapshot = { available: false, buckets: [], observedAt, rateLimitResetCredits: null };
        this.notify();

        return true;
    }

    notify() {
        const snapshot = this.getSnapshot();
        this.events.dispatchEvent(new CustomEvent(RATE_LIMIT_EVENT, { detail: snapshot }));
    }
}

module.exports = { CodexRuntimeService };

import { createRequire } from 'node:module';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { CodexRuntimeService } = require('./codex_runtime_service');

function bucket(limitId, usedPercent, overrides = {}) {
    return {
        credits: null,
        individualLimit: null,
        limitId,
        limitName: limitId === 'codex' ? 'Codex' : null,
        planType: 'plus',
        primary: { resetsAt: 100, usedPercent, windowDurationMins: 300 },
        rateLimitReachedType: null,
        secondary: null,
        ...overrides,
    };
}

describe('CodexRuntimeService', () => {
    it('publishes each confirmed update mismatch once per session and replays latest state', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribeUpdateRequired(listener);

        expect(service.publishUpdateRequired('0.144.6', '0.146.0')).toBe(true);
        expect(service.publishUpdateRequired('0.144.6', '0.146.0')).toBe(false);
        expect(listener).toHaveBeenCalledOnce();
        expect(listener).toHaveBeenCalledWith({ cacheVersion: '0.146.0', runningVersion: '0.144.6' });

        const lateListener = vi.fn();
        service.subscribeUpdateRequired(lateListener);
        expect(lateListener).toHaveBeenCalledWith({ cacheVersion: '0.146.0', runningVersion: '0.144.6' });
    });

    it('normalizes multi-bucket snapshots and publishes current state to subscribers', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);

        expect(service.publishRateLimits({
            rateLimitResetCredits: { availableCount: 0, credits: [] },
            rateLimits: bucket('codex', 10),
            rateLimitsByLimitId: {
                codex: bucket(null, 20),
                review: bucket('review', 40, {
                    primary: null,
                    secondary: { resetsAt: null, usedPercent: 40, windowDurationMins: null },
                }),
            },
        }, 200)).toBe(true);

        expect(service.getSnapshot()).toEqual({
            available: true,
            buckets: [
                expect.objectContaining({ limitId: 'codex', primary: expect.objectContaining({ usedPercent: 20 }) }),
                expect.objectContaining({ limitId: 'review', secondary: expect.objectContaining({ usedPercent: 40 }) }),
            ],
            observedAt: 200,
            rateLimitResetCredits: { availableCount: 0, credits: [] },
        });
        const lateListener = vi.fn();
        service.subscribe(lateListener);
        expect(listener).toHaveBeenCalledOnce();
        expect(lateListener).toHaveBeenCalledWith(service.getSnapshot());
    });

    it('merges sparse updates without erasing other buckets or nullable account fields', () => {
        const service = new CodexRuntimeService();
        service.publishRateLimits({
            rateLimitResetCredits: { availableCount: 1, credits: null },
            rateLimits: bucket('codex', 10),
            rateLimitsByLimitId: {
                codex: bucket('codex', 10),
                review: bucket('review', 40),
            },
        }, 100);

        service.publishRateLimits({rateLimits: bucket('codex', 70, { credits: null, limitName: null, planType: null })}, 101, true);

        expect(service.getSnapshot()).toMatchObject({
            buckets: [
                { credits: null, limitId: 'codex', limitName: 'Codex', planType: 'plus', primary: { usedPercent: 70 } },
                { limitId: 'review', primary: { usedPercent: 40 } },
            ],
            rateLimitResetCredits: { availableCount: 1, credits: null },
        });
    });

    it('accepts valid sparse updates with omitted optional fields', () => {
        const service = new CodexRuntimeService();
        service.publishRateLimits({
            rateLimits: bucket('codex', 20),
            rateLimitsByLimitId: null,
        }, 10);

        expect(service.publishRateLimits({
            rateLimits: {
                limitId: 'codex',
                primary: { usedPercent: 45 },
            },
        }, 11, true)).toBe(true);
        expect(service.getSnapshot()).toMatchObject({
            buckets: [{
                limitId: 'codex',
                limitName: 'Codex',
                primary: { resetsAt: 100, usedPercent: 45, windowDurationMins: 300 },
            }],
            observedAt: 11,
        });
    });

    it('rejects malformed and older reports without erasing newer data', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);
        service.publishRateLimits({ rateLimits: bucket('codex', 80) }, 200);

        expect(service.publishRateLimits({ rateLimits: bucket('codex', 10) }, 199)).toBe(false);
        expect(service.publishRateLimits({ rateLimits: { ...bucket('codex', 10), primary: { usedPercent: 'bad' } } }, 201)).toBe(false);
        expect(service.getSnapshot()).toMatchObject({
            buckets: [{ limitId: 'codex', primary: { usedPercent: 80 } }],
            observedAt: 200,
        });
        expect(listener).toHaveBeenCalledOnce();
    });

    it('publishes unavailable state without fabricating usage and keeps no persistence dependency', () => {
        const service = new CodexRuntimeService();
        const listener = vi.fn();
        service.subscribe(listener);

        expect(service.publishUnavailable(300)).toBe(true);
        expect(service.getSnapshot()).toEqual({
            available: false,
            buckets: [],
            observedAt: 300,
            rateLimitResetCredits: null,
        });
        expect(listener).toHaveBeenCalledWith(service.getSnapshot());
        expect(Object.hasOwn(service, 'persistConversation')).toBe(false);
    });
});

const crypto = require('node:crypto');
const path = require('node:path');
const crossSpawn = require('cross-spawn');

const {
    accumulateUsage,
    createConversation,
    createEventEntry,
    createMessageEntry,
    snapshotConversation,
    transitionConversationStatus,
    updateProviderSession,
} = require('./agent_conversation');
const {
    conversationReference,
    persistConversation,
    persistConversationCheckpoint,
} = require('./agent_conversation_persistence');
const { AgentExecutableResolver } = require('./agent_executable_availability');
const { createAgentEnvironment } = require('./agent_environment');
const { diagnoseCodexCacheError, isCodexCacheError } = require('./agent_codex_cache_diagnostic');
const { logAgentEvent } = require('./agent_file_logger');
const agentInteractions = require('./agent_run_interactions');
const {
    attachRunProtocol,
    createRun,
    createRunResult,
    emitRunEvent,
} = require('./agent_run_state');
const {
    appendAssistantOutput,
    completeAssistantOutput,
    lastMessageEntry,
    nextConversationSequence,
    nextRunSequence,
} = require('./agent_run_transcript');
const {
    readOptionalString,
    requireCommand,
    requireProjectFolder,
    requireString,
} = require('./agent_run_validation');
const { redactSecrets } = require('./agent_secret_redaction');
const { filterCompleteStderrLines, isHiddenStderrLine, stripAnsi } = require('./agent_stderr_filter');
const { STREAMING_EVENT_HANDLERS } = require('./agent_streaming_event_handlers');
const { terminateProcessTree } = require('../process_tree');
const { assertGitRoot, ensureInsideRoot, requireRootPath } = require('../../git/git_commands');

const AGENT_FINISH_GRACE_MS = 5_000;

class AgentRunnerService {
    constructor(dependencies = {}) {
        this.codexRuntimeService = dependencies.codexRuntimeService ?? null;
        this.persistConversation = dependencies.persistConversation
            ?? dependencies.persistTerminalConversation
            ?? persistConversation;
        this.persistConversationCheckpoint = dependencies.persistConversationCheckpoint
            ?? persistConversationCheckpoint;
        this.executableResolver = dependencies.executableResolver ?? new AgentExecutableResolver();
        this.diagnoseCodexCacheError = dependencies.diagnoseCodexCacheError ?? diagnoseCodexCacheError;
        this.clearTimeout = dependencies.clearTimeout ?? clearTimeout;
        this.setTimeout = dependencies.setTimeout ?? setTimeout;
        this.terminateProcessTree = dependencies.terminateProcessTree ?? terminateProcessTree;
        this.handleFinishTimeout = this.handleFinishTimeout.bind(this);
        this.processes = new Map();
        this.runningConversationIds = new Set();
    }

    async run(project, request, onEvent) {
        let resolveCompletion;
        let rejectCompletion;
        const completion = new Promise((resolve, reject) => {
            resolveCompletion = resolve;
            rejectCompletion = reject;
        });
        const onComplete = (exitCode, run) => resolveCompletion(createRunResult(request, exitCode, run));
        const onCompletionError = (error) => rejectCompletion(error);

        await this.start(project, request, onEvent, onComplete, onCompletionError);

        return completion;
    }

    async start(project, requestValue, onEvent, onComplete, onCompletionError) {
        const request = {
            activityOrigin: { kind: 'project' },
            activityProject: project,
            ...requestValue,
        };
        const rootPath = requireRootPath(project);
        await assertGitRoot(rootPath);
        const command = requireCommand(request?.command);
        readOptionalString(request?.actionId, 'actionId');
        const cardPath = readOptionalString(request?.cardPath, 'cardPath');
        const prompt = requireString(request?.prompt, 'prompt');
        const agent = requireString(request?.agent ?? 'generic', 'agent');
        const streaming = request.streaming === true;
        requireProjectFolder(request?.projectFolder);
        if (cardPath) ensureInsideRoot(rootPath, path.join(rootPath, cardPath));

        const id = `agent-turn-${crypto.randomUUID()}`;
        const startedAt = new Date().toISOString();
        const conversationId = request.conversation?.id ?? request.conversationId ?? `agent-${crypto.randomUUID()}`;
        const reference = request.reference ?? conversationReference(request, conversationId);
        const conversation = createConversation(request, conversationId, startedAt, reference);
        let nextSequence = nextConversationSequence(conversation);
        if (this.runningConversationIds.has(conversation.id)) throw new Error(`Agent conversation already has a running turn: ${conversation.id}`);
        const lastMessage = lastMessageEntry(conversation);
        if (request.reuseLastUserMessage) {
            if (lastMessage?.role !== 'user' || lastMessage.content !== prompt) throw new Error('Missing failed-turn user message for agent retry');
        } else {
            conversation.entries.push(createMessageEntry(`${id}-user`, 'user', prompt, startedAt, undefined, nextSequence));
            nextSequence += 1;
        }
        const [configuredExecutable, ...configuredArguments] = command;
        const environment = createAgentEnvironment(process.env);
        const resolvedExecutable = await this.executableResolver.find(configuredExecutable, { cwd: rootPath, env: environment });
        const executable = resolvedExecutable ?? configuredExecutable;
        const argumentsList = streaming ? configuredArguments : [...configuredArguments, prompt];
        const child = crossSpawn(executable, argumentsList, {
            cwd: rootPath,
            detached: process.platform !== 'win32',
            env: environment,
            stdio: ['pipe', 'pipe', 'pipe'],
            // windowsHide: true,
        });
        logAgentEvent('[agent:start]', {
            arguments: configuredArguments,
            cwd: rootPath,
            actionRunId: request.actionRunId ?? null,
            executable,
            pid: child.pid,
            runId: id,
            startedAt,
        });
        const run = createRun({
            agent,
            child,
            conversation,
            environment,
            executable,
            id,
            nextSequence,
            onComplete,
            onCompletionError,
            onEvent,
            reference,
            request,
            startedAt,
            streaming,
        });
        attachRunProtocol(run, {
            onCodexRuntimeEvent: (event) => this.handleCodexRuntimeEvent(event),
            onMalformedOutput: (line) => this.handleMalformedOutput(id, line),
            onProviderEvent: (event) => this.handleProviderEvent(id, event),
            onStreamingEvent: (event) => this.handleStreamingEvent(id, event),
            onStreamingLine: (line) => this.handleStreamingLine(id, line),
            providerConversationId: request.providerConversationId,
            rootPath,
        });
        this.processes.set(id, run);
        this.runningConversationIds.add(conversation.id);

        child.stdout.on('data', (chunk) => this.handleOutput(id, 'stdout', chunk));
        child.stderr.on('data', (chunk) => this.handleOutput(id, 'stderr', chunk));
        child.on('error', (error) => this.handleError(id, error));
        child.stdin.on('error', (error) => this.handleError(id, error));
        child.on('close', (exitCode) => {
            void this.handleClose(id, exitCode ?? 1).finally(run.resolveClosed);
        });
        if (streaming) {
            const initialPrompt = typeof request.contextInput === 'string' && request.contextInput.length > 0
                ? `${request.contextInput}\n\n[User]\n\n${prompt}`
                : prompt;
            try {
                await run.streamingAdapter.start(initialPrompt);
            } catch (error) {
                this.failStreamingRun(run, error);
            }
        } else {
            if (typeof request.contextInput === 'string' && request.contextInput.length > 0) child.stdin.write(request.contextInput);
            child.stdin.end();
        }
        const userMessage = lastMessageEntry(conversation);
        if (!userMessage || userMessage.role !== 'user') throw new Error('Missing current agent user message');
        const conversationSnapshot = snapshotConversation(conversation);
        emitRunEvent(run, {
            continued: !!request.conversation,
            conversation: conversationSnapshot,
            type: 'started',
        });

        return { conversation: conversationSnapshot, reference, runId: id };
    }

    stop(runId) {
        const run = this.requireRun(runId);
        run.cancelled = true;
        run.queuedMessage = null;
        transitionConversationStatus(run.conversation, 'cancelled', new Date().toISOString());
        this.clearFinishTimeout(run);

        return this.ensureTermination(run);
    }

    suspend(runId) {
        const run = this.requireRun(runId);
        run.suspended = true;
        run.queuedMessage = null;
        this.clearFinishTimeout(run);

        return this.ensureTermination(run);
    }

    beginQueuedMessageDraft(runId) {
        return agentInteractions.beginQueuedMessageDraft(this.requireRun(runId));
    }

    setQueuedMessage(runId, sessionId, content, revision) {
        return agentInteractions.setQueuedMessage(this.requireRun(runId), sessionId, content, revision);
    }

    sendQueuedMessage(runId, sessionId, revision) {
        return agentInteractions.sendQueuedMessage(this, this.requireRun(runId), sessionId, revision);
    }

    sendMessage(runId, content) {
        return agentInteractions.sendMessage(this, this.requireStreamingRun(runId), content);
    }

    sendStreamingMessage(run, content) {
        return agentInteractions.sendStreamingMessage(this, run, content);
    }

    answerQuestion(runId, requestId, answers) {
        return agentInteractions.answerQuestion(this, this.requireStreamingRun(runId), requestId, answers);
    }

    answerApproval(runId, requestId, decision) {
        return agentInteractions.answerApproval(this, this.requireStreamingRun(runId), requestId, decision);
    }

    finish(runId) {
        const run = this.requireStreamingRun(runId);
        run.finishing = true;
        run.queuedMessage = null;
        if (!run.turnActive || run.waitingForQuestion) this.beginFinishShutdown(run);
    }

    beginFinishShutdown(run) {
        if (run.finishTimeout !== null && run.finishTimeout !== undefined) return;
        run.finishTimeout = this.setTimeout(this.handleFinishTimeout, AGENT_FINISH_GRACE_MS, run.id);
        run.child.stdin.end();
    }

    clearFinishTimeout(run) {
        if (run.finishTimeout === null || run.finishTimeout === undefined) return;
        this.clearTimeout(run.finishTimeout);
        run.finishTimeout = null;
    }

    async handleFinishTimeout(runId) {
        const run = this.processes.get(runId);
        if (!run) return;
        run.finishTimeout = null;
        console.warn('[agent:finish-timeout]', {
            graceMs: AGENT_FINISH_GRACE_MS,
            pid: run.child.pid,
            runId,
            timestamp: new Date().toISOString(),
        });
        try {
            run.finishForced = await this.ensureTermination(run);
        } catch (error) {
            this.handleError(runId, error);
        }
    }

    stopAll() {
        const completions = [];
        for (const run of this.processes.values()) {
            run.cancelled = true;
            transitionConversationStatus(run.conversation, 'cancelled', new Date().toISOString());
            this.clearFinishTimeout(run);
            completions.push(Promise.all([this.ensureTermination(run), run.closed]));
        }

        return Promise.all(completions);
    }

    ensureTermination(run) {
        run.termination ??= this.terminateProcessTree(run.child);

        return run.termination;
    }

    handleCodexRuntimeEvent(event) {
        if (!this.codexRuntimeService) return;
        if (event.kind === 'unavailable') {
            this.codexRuntimeService.publishUnavailable(event.observedAt);
            return;
        }
        this.codexRuntimeService.publishRateLimits(event.payload, event.observedAt, event.kind === 'update');
    }

    handleOutput(runId, channel, chunk) {
        const run = this.processes.get(runId);
        if (!run) return;

        const content = chunk.toString();
        if (channel === 'stdout' && run.protocolLines) {
            run.protocolLines.push(chunk);
            return;
        }
        if (channel === 'stdout' && run.parser) {
            run.parser.push(chunk);
            return;
        }
        if (channel === 'stderr') {
            run.stderrBuffer += content;
            const filtered = filterCompleteStderrLines(run.stderrBuffer);
            run.stderrBuffer = filtered.remainder;
            if (filtered.content.length === 0) return;
            this.recordStderr(run, filtered.content);
            return;
        }
        this.recordOutput(runId, channel, content);
    }

    recordStderr(run, content) {
        const parts = content.split(/(\r\n|\r|\n)/u);
        for (let index = 0; index < parts.length; index += 2) {
            const line = stripAnsi(parts[index]);
            const delimiter = parts[index + 1] ?? '';
            if (line.length === 0 && delimiter.length === 0) continue;
            if (run.agent !== 'codex' || !isCodexCacheError(line)) {
                this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
                continue;
            }
            if (run.codexCacheErrorReported) continue;
            run.codexCacheErrorReported = true;
            const diagnostic = run.stderrHandling.then(async () => {
                const result = await this.diagnoseCodexCacheError(line, run.executable, run.environment);
                this.recordOutput(run.id, 'stderr', `${result.message}\n`);
                if (result.updateRequired) {
                    this.codexRuntimeService?.publishUpdateRequired(result.runningVersion, result.cacheVersion);
                }
            });
            run.stderrHandling = diagnostic.catch(() => {
                this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
            });
        }
    }

    handleStreamingLine(runId, line) {
        const run = this.processes.get(runId);
        if (!run) return;

        let message;
        try {
            message = JSON.parse(line);
        } catch {
            this.handleMalformedOutput(runId, line);
            return;
        }
        run.protocolHandling = run.protocolHandling
            .then(() => run.streamingAdapter.handleMessage(message))
            .catch((error) => {
                this.failStreamingRun(run, error);
            });
    }

    recordOutput(runId, channel, content) {
        const run = this.processes.get(runId);
        if (!run) return;

        const timestamp = new Date().toISOString();
        const safeContent = redactSecrets(content, run.secretValues);
        if (channel === 'stdout') {
            const { segment } = appendAssistantOutput(run, safeContent, timestamp);
            if (segment.length === 0) return;
            emitRunEvent(run, { content: segment, type: 'output' });
            return;
        }
        run.stderr += safeContent;
        if (run.streaming) {
            emitRunEvent(run, { content: safeContent, type: 'error' });
            return;
        }
        run.conversation.entries.push(createEventEntry(
            `${runId}-error-${run.conversation.entries.length}`,
            'error',
            safeContent,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: safeContent, type: 'error' });
    }

    flushStderr(runId) {
        const run = this.processes.get(runId);
        if (!run || run.stderrBuffer.length === 0) return;

        const content = run.stderrBuffer;
        run.stderrBuffer = '';
        if (!isHiddenStderrLine(content)) this.recordStderr(run, content);
    }

    handleProviderEvent(runId, providerEvent) {
        const run = this.processes.get(runId);
        if (!run) return;

        const timestamp = new Date().toISOString();
        run.turnStarted = run.turnStarted || providerEvent.turnStarted;
        run.missingSession = run.missingSession || providerEvent.missingSession;
        providerEvent.changedPaths.forEach((filePath) => run.changedPaths.add(filePath));
        if (providerEvent.conversationId) run.providerConversationId = providerEvent.conversationId;
        if (providerEvent.usage) run.turnUsage = providerEvent.usage;
        for (const transcriptEvent of providerEvent.transcriptEvents) {
            run.conversation.entries.push(createEventEntry(
                `${runId}-provider-${run.conversation.entries.length}`,
                transcriptEvent.toolType,
                transcriptEvent.content,
                timestamp,
                nextRunSequence(run),
            ));
        }
        if (providerEvent.assistantText.length > 0) {
            const { segment } = appendAssistantOutput(run, providerEvent.assistantText, timestamp);
            if (segment.length > 0) emitRunEvent(run, { content: segment, type: 'output' });
        } else if (providerEvent.errorText.length > 0 && !run.reportedProviderErrors.has(providerEvent.errorText)) {
            const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
            run.reportedProviderErrors.add(providerEvent.errorText);
            run.stderr += `${separator}${providerEvent.errorText}`;
            run.conversation.entries.push(createEventEntry(
                `${runId}-error-${run.conversation.entries.length}`,
                'error',
                providerEvent.errorText,
                timestamp,
                nextRunSequence(run),
            ));
            emitRunEvent(run, { content: providerEvent.errorText, type: 'error' });
        }
    }

    async handleStreamingEvent(runId, event) {
        const run = this.processes.get(runId);
        if (!run) return;

        const handler = STREAMING_EVENT_HANDLERS[event.type];
        if (!handler) return;

        await handler(this, run, event, new Date().toISOString());
    }

    handleMalformedOutput(runId, line) {
        const run = this.processes.get(runId);
        if (!run) return;

        if (!run.streaming) {
            const timestamp = new Date().toISOString();
            const message = `Malformed ${run.agent} JSONL event: ${line}`;
            run.conversation.entries.push(createEventEntry(
                `${runId}-malformed-${run.conversation.entries.length}`,
                'diagnostic',
                message,
                timestamp,
                nextRunSequence(run),
            ));
            return;
        }
        this.failStreamingRun(run, new Error(`Malformed ${run.agent} JSONL event`));
    }

    handleError(runId, error) {
        const run = this.processes.get(runId);
        if (!run) return;

        if (run.streaming) {
            this.failStreamingRun(run, error);
            return;
        }
        const timestamp = new Date().toISOString();
        const message = error instanceof Error ? error.message : 'Agent process failed';
        run.stderr += message;
        run.conversation.entries.push(createEventEntry(
            `${runId}-error-${run.conversation.entries.length}`,
            'error',
            message,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: message, type: 'error' });
    }

    failStreamingRun(run, errorValue) {
        if (run.streamingFailure) return run.termination;

        const error = errorValue instanceof Error ? errorValue : new Error('Streaming agent failed');
        const message = redactSecrets(error.message, run.secretValues);
        const timestamp = new Date().toISOString();
        run.streamingFailure = new Error(message);
        transitionConversationStatus(run.conversation, 'failed', timestamp);
        run.queuedMessage = null;
        run.waitingForQuestion = false;
        run.pendingQuestions = [];
        const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
        run.stderr += `${separator}${message}`;
        run.conversation.entries.push(createEventEntry(
            `${run.id}-error-${run.conversation.entries.length}`,
            'error',
            message,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: message, type: 'error' });
        emitRunEvent(run, { state: 'failed', type: 'state' });
        try {
            run.child.stdin.end();
        } catch {
            // Process-tree termination below remains authoritative.
        }

        return this.ensureTermination(run);
    }

    async handleClose(runId, exitCode) {
        const run = this.processes.get(runId);
        if (!run) return;
        this.clearFinishTimeout(run);

        try {
            if (run.termination) await run.termination;
            run.parser?.finish();
            run.protocolLines?.finish();
            await run.protocolHandling;
            this.flushStderr(runId);
            await run.stderrHandling;
            const completedAt = new Date().toISOString();
            if (run.streaming && !run.finishing && !run.cancelled && !run.streamingFailure && !run.suspended) {
                run.streamingFailure = new Error('Streaming agent process exited before Finish');
                const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
                run.stderr += `${separator}${run.streamingFailure.message}`;
            }
            const succeeded = (exitCode === 0 || (run.finishing && run.finishForced))
                && !run.missingSession
                && !run.cancelled
                && !run.streamingFailure
                && (!run.streaming || run.finishing);
            completeAssistantOutput(run, completedAt);
            if (succeeded) {
                const synchronizedMessage = lastMessageEntry(run.conversation);
                updateProviderSession(run, synchronizedMessage.id, completedAt);
                if (run.turnUsage) run.conversation.usage = accumulateUsage(run.conversation.usage, run.turnUsage);
            }
            const preserveWaitingState = run.suspended && run.conversation.status === 'waitingForInput';
            run.conversation.completedAt = preserveWaitingState ? null : completedAt;
            const status = preserveWaitingState
                ? 'waitingForInput'
                : run.cancelled ? 'cancelled' : succeeded ? 'completed' : 'failed';
            transitionConversationStatus(run.conversation, status, completedAt);
            const continuedTurnFailedBeforeStart = !!run.request.conversation
                && !run.turnStarted
                && !succeeded
                && !run.cancelled
                && !run.suspended;
            logAgentEvent('[agent:complete]', {
                completedAt,
                durationMs: Date.parse(completedAt) - Date.parse(run.startedAt),
                actionRunId: run.request.actionRunId ?? null,
                exitCode,
                pid: run.child.pid,
                runId,
            });
            await run.persistence;
            if (!continuedTurnFailedBeforeStart) await this.persistConversation(run);
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
            emitRunEvent(run, { conversation: run.conversation, type: 'closed' });
            if (run.onComplete) run.onComplete(succeeded ? 0 : exitCode || 1, run);
        } catch (error) {
            if (run.onCompletionError) run.onCompletionError(error);
        } finally {
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
        }
    }

    requireRun(runId) {
        const run = this.processes.get(runId);
        if (!run) throw new Error(`Agent run is not active: ${runId}`);

        return run;
    }

    persistCheckpoint(run) {
        const snapshot = { ...run, conversation: snapshotConversation(run.conversation) };
        const write = run.persistence.then(() => this.persistConversationCheckpoint(snapshot));
        run.persistence = write.catch(() => undefined);

        return write;
    }

    requireStreamingRun(runId) {
        const run = this.requireRun(runId);
        if (!run.streaming) throw new Error(`Agent run is not streaming: ${runId}`);

        return run;
    }
}

module.exports = { AGENT_FINISH_GRACE_MS, AgentRunnerService };

const { execFile } = require('node:child_process');
const path = require('node:path');
const { promisify } = require('node:util');

const execFileAsync = promisify(execFile);

function readEnvironmentValue(env, name) {
    const matchingName = Object.keys(env).find((key) => key.toLowerCase() === name.toLowerCase());

    return matchingName ? env[matchingName] : '';
}

function selectLocatedExecutable(stdout, executable, platform, env) {
    const candidates = String(stdout).split(/\r?\n/u).map((candidate) => candidate.trim()).filter((candidate) => candidate.length > 0);
    if (platform !== 'win32' || path.extname(executable).length > 0) return candidates[0] ?? null;

    const pathExtensions = readEnvironmentValue(env, 'PATHEXT').split(';').map((extension) => extension.toUpperCase());

    return candidates.find((candidate) => pathExtensions.includes(path.extname(candidate).toUpperCase())) ?? candidates[0] ?? null;
}

class AgentExecutableResolver {
    constructor(dependencies = {}) {
        this.execFileAsync = dependencies.execFileAsync ?? execFileAsync;
        this.platform = dependencies.platform ?? process.platform;
        this.resolutions = new Map();
    }

    cacheKey(executable, options) {
        const env = options.env ?? process.env;
        const cwd = options.cwd ?? process.cwd();

        return JSON.stringify([
            executable,
            cwd,
            readEnvironmentValue(env, 'PATH'),
            readEnvironmentValue(env, 'PATHEXT'),
            this.platform,
        ]);
    }

    async find(executable, options = {}) {
        const key = this.cacheKey(executable, options);
        const cached = this.resolutions.get(key);
        if (cached) return cached;

        const resolution = this.locate(executable, options);
        this.resolutions.set(key, resolution);
        const resolvedExecutable = await resolution;
        if (!resolvedExecutable) this.resolutions.delete(key);

        return resolvedExecutable;
    }

    async locate(executable, options) {
        const env = options.env ?? process.env;
        const cwd = options.cwd ?? process.cwd();
        const locator = this.platform === 'win32' ? 'where.exe' : 'which';

        try {
            const { stdout } = await this.execFileAsync(locator, [executable], { cwd, env });

            return selectLocatedExecutable(stdout, executable, this.platform, env);
        } catch {
            return null;
        }
    }
}

function executableFromCommand(command) {
    if (!Array.isArray(command) || typeof command[0] !== 'string' || command[0].length === 0) {
        throw new Error('Invalid agent command');
    }

    return command[0];
}

/** Check configured agent commands without starting provider processes. */
async function loadAgentExecutableAvailability(profiles, options = {}) {
    const resolver = options.resolver ?? new AgentExecutableResolver(options);
    const availabilityEntries = await Promise.all(profiles.map(async ({ command, name }) => {
        const executable = executableFromCommand(command);
        const available = !!await resolver.find(executable);
        const error = available ? null : `Executable not found for ${name}: ${executable}`;

        return [name, { available, error }];
    }));

    return Object.fromEntries(availabilityEntries);
}

module.exports = { AgentExecutableResolver, executableFromCommand, loadAgentExecutableAvailability };

