import {
    getElectronCodexRuntimeBridge,
    type CodexRateLimitSnapshot,
    type ElectronCodexRuntimeBridge,
} from '../../data/electron_codex_runtime_bridge'
import { register } from '../service_injector'

export interface CodexRateLimitState {
    receivedAt: number | null
    snapshot: CodexRateLimitSnapshot | null
    stale: boolean
}

const INITIAL_STATE: CodexRateLimitState = { receivedAt: null, snapshot: null, stale: false }
const UNIX_MILLISECONDS_THRESHOLD = 1_000_000_000_000

function resetTimeMilliseconds(resetTime: number) {
    return resetTime < UNIX_MILLISECONDS_THRESHOLD ? resetTime * 1000 : resetTime
}

function firstResetTime(snapshot: CodexRateLimitSnapshot) {
    const resetTimes = snapshot.buckets.flatMap(({ primary, secondary }) => (
        [primary?.resetsAt, secondary?.resetsAt]
            .filter((resetTime): resetTime is number => resetTime !== null && resetTime !== undefined)
            .map(resetTimeMilliseconds)
    ))

    return resetTimes.length > 0 ? Math.min(...resetTimes) : null
}

function validSnapshot(snapshot: CodexRateLimitSnapshot) {
    return Number.isFinite(snapshot.observedAt)
        && (!snapshot.available || snapshot.buckets.length > 0)
        && snapshot.buckets.every(({ primary, secondary }) => (
            (!primary || Number.isFinite(primary.usedPercent))
            && (!secondary || Number.isFinite(secondary.usedPercent))
        ))
}

/** Owns current account-wide Codex rate limits for this renderer process only. */
export class CodexRateLimitService extends EventTarget {
    private bridge: ElectronCodexRuntimeBridge | null = null
    private expirationTimer: ReturnType<typeof setTimeout> | null = null
    private state: CodexRateLimitState = INITIAL_STATE
    private unsubscribeConnection: (() => void) | null = null
    private unsubscribeRateLimits: (() => void) | null = null

    constructor() {
        super()
        register('codexRateLimitService', this)
    }

    getState() {
        return this.state
    }

    start() {
        const bridge = getElectronCodexRuntimeBridge()
        if (bridge === this.bridge && this.unsubscribeRateLimits) return

        this.unsubscribe()
        this.bridge = bridge
        this.setState(INITIAL_STATE)
        if (!bridge) return

        this.unsubscribeRateLimits = bridge.onCodexRateLimits((snapshot) => this.acceptSnapshot(bridge, snapshot))
        this.unsubscribeConnection = bridge.onConnectionChanged?.((connected) => this.handleConnectionChange(bridge, connected)) ?? null
        void this.refresh(bridge)
    }

    stop() {
        this.unsubscribe()
        this.bridge = null
        this.setState(INITIAL_STATE)
    }

    private acceptSnapshot(bridge: ElectronCodexRuntimeBridge, snapshot: CodexRateLimitSnapshot) {
        if (bridge !== this.bridge || !validSnapshot(snapshot)) return
        const currentObservedAt = this.state.snapshot?.observedAt
        if (currentObservedAt !== undefined && snapshot.observedAt < currentObservedAt) return

        const receivedAt = Date.now()
        this.setState({ receivedAt, snapshot, stale: false })
        this.scheduleExpiration(snapshot, receivedAt)
    }

    private async refresh(bridge: ElectronCodexRuntimeBridge) {
        try {
            const snapshot = await bridge.getCodexRateLimits()
            if (snapshot) this.acceptSnapshot(bridge, snapshot)
        } catch {
            if (bridge === this.bridge) this.markStale()
        }
    }

    private handleConnectionChange(bridge: ElectronCodexRuntimeBridge, connected: boolean) {
        if (bridge !== this.bridge) return
        if (!connected) {
            this.markStale()
            return
        }

        void this.refresh(bridge)
    }

    private scheduleExpiration(snapshot: CodexRateLimitSnapshot, receivedAt: number) {
        if (this.expirationTimer) clearTimeout(this.expirationTimer)
        this.expirationTimer = null
        if (!snapshot.available) return
        const resetTime = firstResetTime(snapshot)
        if (resetTime === null) return
        const localResetTime = receivedAt + resetTime - snapshot.observedAt
        const delay = Math.max(0, localResetTime - Date.now())
        if (delay === 0) {
            this.markStale()
            return
        }
        this.expirationTimer = setTimeout(() => this.markStale(), delay)
    }

    private markStale() {
        if (!this.state.snapshot || this.state.stale) return

        this.setState({ ...this.state, stale: true })
    }

    private unsubscribe() {
        this.unsubscribeRateLimits?.()
        this.unsubscribeConnection?.()
        this.unsubscribeRateLimits = null
        this.unsubscribeConnection = null
        if (this.expirationTimer) clearTimeout(this.expirationTimer)
        this.expirationTimer = null
    }

    private setState(state: CodexRateLimitState) {
        if (
            state.receivedAt === this.state.receivedAt
            && state.snapshot === this.state.snapshot
            && state.stale === this.state.stale
        ) return

        this.state = state
        this.dispatchEvent(new CustomEvent('changed'))
    }
}

export const codexRateLimitService = new CodexRateLimitService()

import { afterEach, describe, expect, it, vi } from 'vitest'
import {
    setCodexRuntimeBridgeOverride,
    type CodexRateLimitSnapshot,
    type ElectronCodexRuntimeBridge,
} from '../../data/electron_codex_runtime_bridge'
import { CodexRateLimitService } from './codex_rate_limit_service'

function snapshot(
    observedAt: number,
    usedPercent = 25,
    resetsAt = Math.floor(observedAt / 1000) + 3600,
): CodexRateLimitSnapshot {
    return {
        available: true,
        buckets: [{
            credits: null,
            individualLimit: null,
            limitId: 'codex',
            limitName: 'Codex',
            planType: 'plus',
            primary: { resetsAt, usedPercent, windowDurationMins: 300 },
            rateLimitReachedType: null,
            secondary: null,
        }],
        observedAt,
        rateLimitResetCredits: null,
    }
}

function bridge(initialSnapshot: CodexRateLimitSnapshot | null = null) {
    let rateLimitListener: ((value: CodexRateLimitSnapshot) => void) | null = null
    let connectionListener: ((connected: boolean) => void) | null = null
    const value: ElectronCodexRuntimeBridge = {
        getCodexRateLimits: vi.fn(async () => initialSnapshot),
        onCodexRateLimits: vi.fn((listener) => {
            rateLimitListener = listener

            return vi.fn()
        }),
        onCodexUpdateRequired: vi.fn(() => vi.fn()),
        onConnectionChanged: vi.fn((listener) => {
            connectionListener = listener

            return vi.fn()
        }),
        updateCodexCli: vi.fn(async () => undefined),
    }

    return {
        emitConnection: (connected: boolean) => connectionListener?.(connected),
        emitSnapshot: (nextSnapshot: CodexRateLimitSnapshot) => rateLimitListener?.(nextSnapshot),
        value,
    }
}

describe('CodexRateLimitService', () => {
    afterEach(() => {
        setCodexRuntimeBridgeOverride(null)
        vi.useRealTimers()
    })

    it('reads current limits, subscribes, and replaces the runtime snapshot', async () => {
        const initial = snapshot(1, 10)
        const source = bridge(initial)
        setCodexRuntimeBridgeOverride(source.value)
        const service = new CodexRateLimitService()

        service.start()
        await vi.waitFor(() => expect(service.getState().snapshot).toBe(initial))
        const updated = snapshot(2, 40)
        source.emitSnapshot(updated)

        expect(service.getState()).toEqual({ receivedAt: expect.any(Number), snapshot: updated, stale: false })
        expect(source.value.onCodexRateLimits).toHaveBeenCalledOnce()
        service.stop()
    })

    it('keeps the newest observation when read and subscription race', async () => {
        let resolveRead!: (value: CodexRateLimitSnapshot | null) => void
        const source = bridge()
        source.value.getCodexRateLimits = vi.fn(() => new Promise<CodexRateLimitSnapshot | null>((resolve) => {
            resolveRead = resolve
        }))
        setCodexRuntimeBridgeOverride(source.value)
        const service = new CodexRateLimitService()
        service.start()
        const newest = snapshot(20, 60)
        source.emitSnapshot(newest)
        resolveRead(snapshot(10, 20))
        await Promise.resolve()

        expect(service.getState().snapshot).toBe(newest)
        service.stop()
    })

    it('marks data stale on disconnect and refreshes on reconnect', async () => {
        const source = bridge(snapshot(1))
        setCodexRuntimeBridgeOverride(source.value)
        const service = new CodexRateLimitService()
        service.start()
        await vi.waitFor(() => expect(service.getState().snapshot).not.toBeNull())

        source.emitConnection(false)
        expect(service.getState().stale).toBe(true)
        source.emitConnection(true)

        await vi.waitFor(() => expect(source.value.getCodexRateLimits).toHaveBeenCalledTimes(2))
        expect(service.getState().stale).toBe(false)
        service.stop()
    })

    it('marks a snapshot stale when its first reset window expires', async () => {
        vi.useFakeTimers()
        vi.setSystemTime(new Date('2026-07-28T10:00:00.000Z'))
        const observedAt = Date.now()
        const resetTime = Math.floor(observedAt / 1000) + 60
        const source = bridge(snapshot(observedAt, 25, resetTime))
        setCodexRuntimeBridgeOverride(source.value)
        const service = new CodexRateLimitService()
        service.start()
        await vi.runAllTicks()

        await vi.advanceTimersByTimeAsync(60_000)

        expect(service.getState().stale).toBe(true)
        service.stop()
    })

    it('anchors expiration to local receipt time when remote clock differs', async () => {
        vi.useFakeTimers()
        vi.setSystemTime(new Date('2026-07-28T10:00:00.000Z'))
        const remoteObservedAt = Date.parse('2026-07-28T12:00:00.000Z')
        const remoteResetTime = Date.parse('2026-07-28T13:00:00.000Z') / 1000
        const source = bridge(snapshot(remoteObservedAt, 25, remoteResetTime))
        setCodexRuntimeBridgeOverride(source.value)
        const service = new CodexRateLimitService()
        service.start()
        await vi.runAllTicks()

        await vi.advanceTimersByTimeAsync(59 * 60_000)
        expect(service.getState().stale).toBe(false)
        await vi.advanceTimersByTimeAsync(60_000)
        expect(service.getState().stale).toBe(true)
        service.stop()
    })

    it('hides unavailable state and never uses browser persistence', async () => {
        const getItem = vi.spyOn(Storage.prototype, 'getItem')
        const setItem = vi.spyOn(Storage.prototype, 'setItem')
        const unavailable: CodexRateLimitSnapshot = {
            available: false,
            buckets: [],
            observedAt: 1,
            rateLimitResetCredits: null,
        }
        const source = bridge(unavailable)
        setCodexRuntimeBridgeOverride(source.value)
        const service = new CodexRateLimitService()
        service.start()
        await vi.waitFor(() => expect(service.getState().snapshot).toBe(unavailable))

        expect(getItem).not.toHaveBeenCalled()
        expect(setItem).not.toHaveBeenCalled()
        getItem.mockRestore()
        setItem.mockRestore()
        service.stop()
    })
})

