3	const CLAUDE_USAGE_POLL_COOLDOWN_MS = 120_000;
4	const MONTHS = new Map([
5	    ['jan', 0], ['feb', 1], ['mar', 2], ['apr', 3], ['may', 4], ['jun', 5],
6	    ['jul', 6], ['aug', 7], ['sep', 8], ['oct', 9], ['nov', 10], ['dec', 11],
7	]);
8	const WINDOW_PATTERNS = [
9	    { id: 'five_hour', pattern: /^Current session:\s*(\d{1,3})% used\s*·\s*resets\s+([A-Za-z]{3})\s+(\d{1,2}),\s+(\d{1,2}):(\d{2})(am|pm)\s+\(([^)]+)\)\s*$/iu },
10	    { id: 'weekly', pattern: /^Current week \(all models\):\s*(\d{1,3})% used\s*·\s*resets\s+([A-Za-z]{3})\s+(\d{1,2}),\s+(\d{1,2}):(\d{2})(am|pm)\s+\(([^)]+)\)\s*$/iu },
11	];
