13	function datePartsInTimeZone(timestamp, timeZone) {
14	    const formatter = new Intl.DateTimeFormat('en-US', {
15	        day: '2-digit',
16	        hour: '2-digit',
17	        hourCycle: 'h23',
18	        minute: '2-digit',
19	        month: '2-digit',
20	        second: '2-digit',
21	        timeZone,
22	        year: 'numeric',
23	    });
24	    const parts = Object.fromEntries(formatter.formatToParts(new Date(timestamp)).map(({ type, value }) => [type, value]));
25	
26	    return {
27	        day: Number(parts.day),
28	        hour: Number(parts.hour),
29	        minute: Number(parts.minute),
30	        month: Number(parts.month) - 1,
31	        second: Number(parts.second),
32	        year: Number(parts.year),
33	    };
34	}
35	
36	function matchingDateParts(left, right) {
37	    return left.day === right.day
38	        && left.hour === right.hour
39	        && left.minute === right.minute
40	        && left.month === right.month
41	        && left.year === right.year;
42	}
43	
44	function localDateTimeToUnixMs(parts, timeZone) {
45	    const targetAsUtc = Date.UTC(parts.year, parts.month, parts.day, parts.hour, parts.minute);
46	    let timestamp = targetAsUtc;
47	    for (let index = 0; index < 3; index += 1) {
48	        const zoned = datePartsInTimeZone(timestamp, timeZone);
49	        const representedAsUtc = Date.UTC(zoned.year, zoned.month, zoned.day, zoned.hour, zoned.minute, zoned.second);
50	        timestamp = targetAsUtc - (representedAsUtc - timestamp);
51	    }
52	    if (!matchingDateParts(datePartsInTimeZone(timestamp, timeZone), parts)) throw new Error('Invalid Claude reset time');
53	
54	    return timestamp;
55	}
56	
57	function resetTimestamp(match, observedAt) {
58	    const [, , monthName, dayText, hourText, minuteText, meridiem, timeZone] = match;
59	    const month = MONTHS.get(monthName.toLowerCase());
60	    if (month === undefined) throw new Error('Invalid Claude reset month');
61	    const observedYear = datePartsInTimeZone(observedAt, timeZone).year;
62	    const hourValue = Number(hourText);
63	    if (hourValue < 1 || hourValue > 12) throw new Error('Invalid Claude reset hour');
64	    const hour = (hourValue % 12) + (meridiem.toLowerCase() === 'pm' ? 12 : 0);
65	    const baseParts = { day: Number(dayText), hour, minute: Number(minuteText), month };
66	    const candidates = [observedYear - 1, observedYear, observedYear + 1].map((year) => (
67	        localDateTimeToUnixMs({ ...baseParts, year }, timeZone)
68	    ));
69	
70	    return candidates.reduce((nearest, candidate) => (
71	        Math.abs(candidate - observedAt) < Math.abs(nearest - observedAt) ? candidate : nearest
72	    ));
73	}
