75	function parseClaudeUsageOutput(output, observedAt) {
76	    if (typeof output !== 'string' || !Number.isFinite(observedAt)) return null;
77	    const lines = output.split(/\r?\n/u).map((line) => line.trim()).filter((line) => line.length > 0);
78	    try {
79	        const windows = WINDOW_PATTERNS.map(({ id, pattern }) => {
80	            const matchingLines = lines.map((line) => pattern.exec(line)).filter((match) => match !== null);
81	            if (matchingLines.length !== 1) throw new Error('Missing Claude usage window');
82	            const match = matchingLines[0];
83	            const usedPercent = Number(match[1]);
84	            if (!Number.isInteger(usedPercent) || usedPercent < 0 || usedPercent > 100) throw new Error('Invalid Claude usage percent');
85	
86	            return { id, resetsAt: resetTimestamp(match, observedAt), usedPercent };
87	        });
88	
89	        return { windows };
90	    } catch {
91	        return null;
92	    }
93	}
