95	function collectProcessOutput(child) {
96	    return new Promise((resolve, reject) => {
97	        let stdout = '';
98	        let settled = false;
99	        child.stdout.on('data', (chunk) => {
100	            stdout += chunk.toString();
101	        });
102	        child.on('error', (error) => {
103	            if (settled) return;
104	            settled = true;
105	            reject(error);
106	        });
107	        child.on('close', (exitCode) => {
108	            if (settled) return;
109	            settled = true;
110	            resolve({ exitCode: exitCode ?? 1, stdout });
111	        });
112	        child.stdin.end('/usage\n');
113	    });
114	}
