116	/** Runs Claude `/usage` after Claude output, with a two-minute maximum frequency. */
117	class ClaudeUsagePoller {
118	    constructor(dependencies = {}) {
119	        this.clearTimeout = dependencies.clearTimeout ?? clearTimeout;
120	        this.cooldownMs = dependencies.cooldownMs ?? CLAUDE_USAGE_POLL_COOLDOWN_MS;
121	        this.cwd = dependencies.cwd ?? process.cwd();
122	        this.env = dependencies.env ?? process.env;
123	        this.executableResolver = dependencies.executableResolver;
124	        this.now = dependencies.now ?? Date.now;
125	        this.onRuntimeEvent = dependencies.onRuntimeEvent;
126	        this.setTimeout = dependencies.setTimeout ?? setTimeout;
127	        this.spawn = dependencies.spawn ?? crossSpawn;
128	        this.activePoll = null;
129	        this.lastPollStartedAt = Number.NEGATIVE_INFINITY;
130	        this.pending = false;
131	        this.pendingTimer = null;
132	        this.stopped = false;
133	        if (!this.executableResolver) throw new Error('Claude usage poller requires an executable resolver');
134	        if (typeof this.onRuntimeEvent !== 'function') throw new Error('Claude usage poller requires a runtime event listener');
135	    }
136	
137	    requestPoll() {
138	        if (this.stopped) return;
139	        this.pending = true;
140	        this.schedulePendingPoll();
141	    }
142	
143	    stop() {
144	        this.stopped = true;
145	        this.pending = false;
146	        if (this.pendingTimer) this.clearTimeout(this.pendingTimer);
147	        this.pendingTimer = null;
148	    }
149	
150	    schedulePendingPoll() {
151	        if (this.stopped || !this.pending || this.activePoll || this.pendingTimer) return;
152	        const delay = Math.max(0, this.cooldownMs - (this.now() - this.lastPollStartedAt));
153	        if (delay === 0) {
154	            this.pending = false;
155	            this.activePoll = this.runPendingPoll();
156	            return;
157	        }
158	        this.pendingTimer = this.setTimeout(() => {
159	            this.pendingTimer = null;
160	            this.schedulePendingPoll();
161	        }, delay);
162	    }
163	
164	    async runPendingPoll() {
165	        await this.poll();
166	        this.activePoll = null;
167	        this.schedulePendingPoll();
168	    }
169	
170	    async poll() {
171	        this.lastPollStartedAt = this.now();
172	        const observedAt = this.now();
173	        try {
174	            const executable = await this.executableResolver.find('claude', { cwd: this.cwd, env: this.env }) ?? 'claude';
175	            const child = this.spawn(executable, [], { cwd: this.cwd, env: this.env, stdio: ['pipe', 'pipe', 'pipe'] });
176	            const { exitCode, stdout } = await collectProcessOutput(child);
177	            if (exitCode !== 0) {
178	                await this.onRuntimeEvent({ kind: 'unavailable', observedAt: this.now() });
179	                return;
180	            }
181	            const payload = parseClaudeUsageOutput(stdout, observedAt);
182	            if (payload) await this.onRuntimeEvent({ kind: 'snapshot', observedAt, payload });
183	        } catch {
184	            await this.onRuntimeEvent({ kind: 'unavailable', observedAt: this.now() });
185	        }
186	    }
187	}
